import 'package:flutter/material.dart';import '../widgets/ui.dart';import '../data/sai_repository.dart';import '../models/roles.dart';
class CoursesScreen extends StatelessWidget{const CoursesScreen({super.key,required this.repo,required this.open});final SaiRepository repo;final void Function(Feature) open;@override Widget build(BuildContext context)=>SaiPage(title:'المقررات والدروس',subtitle:'الصفوف والبرامج المسجلة',children:[const SaiSection(title:'البرامج الأكاديمية'),AsyncList(future:repo.classes(),builder:(rows)=>Column(children:[for(final r in rows)SaiTile(title:r['name']?.toString()??'صف',subtitle:'${r['program']??''} · السعة ${r['capacity']??'—'}',icon:Icons.menu_book_outlined,onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>CourseDetailScreen(row:r,repo:repo)))])))]);}
class CourseDetailScreen extends StatelessWidget{const CourseDetailScreen({super.key,required this.row,required this.repo});final Map<String,dynamic> row;final SaiRepository repo;@override Widget build(BuildContext context)=>SaiPage(title:row['name']?.toString()??'المقرر',children:[SaiTile(title:'البرنامج',subtitle:row['program']?.toString(),icon:Icons.school_outlined),SaiTile(title:'السعة',subtitle:'${row['capacity']}',icon:Icons.people_outline),const Padding(padding:EdgeInsets.all(18),child:Text('لم يتم العثور على جداول محتوى الدروس في مخطط 001–007 المراجع. لا يتم عرض دروس وهمية؛ اربط وحدة المحتوى عند اعتماد مخططها.'))]);}
